IEnumerable<Attempt> inMemory = attempts;
IQueryable<Attempt> remote = attempts.AsQueryable();

var local = inMemory.Where(a => a.Score >= 50);  // Func — runs here
var tree  = remote.Where(a => a.Score >= 50);    // Expression — provider decides

// Force a tree even without IQueryable:
Expression<Func<Attempt, bool>> explicitTree = a => a.Score >= 50;
Func<Attempt, bool> compiled = explicitTree.Compile(); // back to in-process

IQueryable<Attempt> q = remote.Where(a => a.Tenant == tenant);

// From here, lambdas may use any in-memory C# — they will not be translated.
IEnumerable<Attempt> local = q.AsEnumerable()
    .Where(a => CustomScoreCurve(a) > 0.8);

static double CustomScoreCurve(Attempt a) => a.Score / 100.0 * 1.2;

// Remote chain — provider may translate both Where clauses
var remoteQuery = dbSet
    .Where(a => a.Tenant == tenant)
    .Where(a => a.Score >= 50)
    .ToList(); // wall: pulls rows into memory

// From here, full C# is available — but data is already in RAM
var enriched = remoteQuery.Where(a => a.Status.Equals("pass", StringComparison.Ordinal));

// IEnumerable — any C# in the lambda:
var local = attempts.Where(a => CustomCurve(a.Score) > 0.8);

// IQueryable — only translatable expression trees:
// var remote = dbSet.Where(a => CustomCurve(a.Score) > 0.8); // often throws

var safe = dbSet.Where(a => a.Score >= 50).ToList() // provider translates
    .Where(a => CustomCurve(a.Score) > 0.8);          // Func after wall

static double CustomCurve(double s) => s / 100.0 * 1.2;
